use App\Core\Database;
use App\Services\AutomaticJudgeBrowserService;
use App\Services\JudgingCriteriaService;
use App\Services\ScoringFlightService;
use App\Services\RoleAdvancementService;

$pdo=Database::connection();
$token=trim((string)($_GET['token']??$_POST['token']??''));
$session=AutomaticJudgeBrowserService::byToken($pdo,$token);
if(!$session||($session['scoring_mode']??'')!=='automated'){
 if($_SERVER['REQUEST_METHOD']==='POST'&&isset($_POST['ajax'])){while(ob_get_level()>0)ob_end_clean();http_response_code(409);header('Content-Type: application/json; charset=utf-8');header('Cache-Control: no-store');echo json_encode(['ok'=>false,'error'=>'This judge link was refreshed or expired. Open the latest secure judge link and continue scoring.'],JSON_UNESCAPED_SLASHES);exit;}
 http_response_code(404);exit('This judge link was refreshed or expired. Open the latest secure judge link.');
}
$sessionId=(int)$session['id'];$roundId=(int)$session['round_id'];$judgeId=(int)$session['judge_id'];
$flightSummary=ScoringFlightService::summary($pdo,$roundId,false);$flightCount=(int)($flightSummary['flight_count']??0);$activeFlight=max(1,(int)($flightSummary['active_flight']??1));$flightsEnabled=$flightCount>0;$viewRound=$flightsEnabled?max(1,min($flightCount,(int)($_GET['scoring_round']??$_POST['scoring_round']??1))):1;
if(isset($_GET['status'])){judgeJson(['status'=>$session['status'],'criteria_required'=>JudgingCriteriaService::requiresAcceptance($session),'active_flight'=>$activeFlight,'flight_count'=>$flightCount]);}
AutomaticJudgeBrowserService::markOpened($pdo,$sessionId);
$locked=(string)$session['status']==='submitted';$isFinal=(string)$session['round_type']==='final';$error='';$notice='';

$roundStmt=$pdo->prepare('SELECT yes_count,callback_count,yes_weight,alt1_weight,alt2_weight,alt3_weight FROM bdc_scoring_rounds WHERE id=:round');
$roundStmt->execute(['round'=>$roundId]);$weights=$roundStmt->fetch()?:['yes_count'=>10,'yes_weight'=>10,'alt1_weight'=>4.5,'alt2_weight'=>4.3,'alt3_weight'=>4.2];
$yesLimit=max(1,(int)($weights['yes_count']??10));
$configuredFinalRankLimit=max(1,(int)($weights['callback_count']??10));
$judgeOrdinal=static function(int $number):string{$mod100=$number%100;if($mod100>=11&&$mod100<=13)return $number.'th';return $number.(match($number%10){1=>'st',2=>'nd',3=>'rd',default=>'th'});};
$selectionRoundLabel=(string)$session['round_type']==='semifinal'?'Semifinal':'Heats';
$a1Place=$judgeOrdinal($yesLimit+1);$a2Place=$judgeOrdinal($yesLimit+2);$a3Place=$judgeOrdinal($yesLimit+3);

$roleCountStmt=$pdo->prepare("SELECT dance_role,COUNT(*) total FROM bdc_scoring_entries WHERE round_id=:round AND entry_status='active' GROUP BY dance_role");
$roleCountStmt->execute(['round'=>$roundId]);$allRoleCounts=['leader'=>0,'follower'=>0];
foreach($roleCountStmt->fetchAll() as $countRow){$countRole=(string)$countRow['dance_role'];if(isset($allRoleCounts[$countRole]))$allRoleCounts[$countRole]=(int)$countRow['total'];}
$rolePlan=RoleAdvancementService::roundPlan($allRoleCounts['leader'],$allRoleCounts['follower'],$yesLimit);

function judgeJson(array $data,int $status=200):never{while(ob_get_level()>0)ob_end_clean();http_response_code($status);header('Content-Type: application/json; charset=utf-8');header('Cache-Control: no-store');echo json_encode($data,JSON_UNESCAPED_SLASHES|JSON_UNESCAPED_UNICODE);exit;}

function heatsSelectionState(PDO $pdo,int $roundId,int $judgeId,string $role):array
{
    $stmt=$pdo->prepare("SELECT
        SUM(CASE WHEN m.mark_type='yes' THEN 1 ELSE 0 END) yes_count,
        SUM(CASE WHEN m.mark_type='alt' AND m.alt_rank=1 THEN 1 ELSE 0 END) alt1_count,
        SUM(CASE WHEN m.mark_type='alt' AND m.alt_rank=2 THEN 1 ELSE 0 END) alt2_count,
        SUM(CASE WHEN m.mark_type='alt' AND m.alt_rank=3 THEN 1 ELSE 0 END) alt3_count
        FROM bdc_scoring_marks m
        JOIN bdc_scoring_entries e ON e.id=m.entry_id
        WHERE m.round_id=:round AND m.judge_id=:judge AND e.dance_role=:role AND e.entry_status='active'");
    $stmt->execute(['round'=>$roundId,'judge'=>$judgeId,'role'=>$role]);
    $row=$stmt->fetch()?:[];
    return ['yes'=>(int)($row['yes_count']??0),'A1'=>(int)($row['alt1_count']??0),'A2'=>(int)($row['alt2_count']??0),'A3'=>(int)($row['alt3_count']??0)];
}

function saveHeatsJudgeMark(PDO $pdo,int $roundId,int $judgeId,int $entryId,string $raw,array $weights):array
{
    $raw=strtoupper(trim($raw));
    $entry=$pdo->prepare("SELECT e.id,e.dance_role,j.scoring_scope FROM bdc_scoring_entries e JOIN bdc_scoring_judges j ON j.id=:judge WHERE e.id=:entry AND e.round_id=:round AND e.entry_status='active'");
    $entry->execute(['judge'=>$judgeId,'entry'=>$entryId,'round'=>$roundId]);$row=$entry->fetch();
    if(!$row)throw new RuntimeException('Competitor is not available for this round.');
    $role=(string)$row['dance_role'];
    if(!in_array((string)$row['scoring_scope'],['all',$role],true))throw new RuntimeException('This competitor is outside your assigned judging panel.');
    if($raw===''||$raw==='NO'){$pdo->prepare('DELETE FROM bdc_scoring_marks WHERE round_id=:round AND entry_id=:entry AND judge_id=:judge')->execute(['round'=>$roundId,'entry'=>$entryId,'judge'=>$judgeId]);return heatsSelectionState($pdo,$roundId,$judgeId,$role);}
    $type='';$alt=null;$weight=0.0;
    if(in_array($raw,['1','Y','YES'],true)){$type='yes';$weight=(float)$weights['yes_weight'];}
    elseif(in_array($raw,['A1','2'],true)){$type='alt';$alt=1;$weight=(float)$weights['alt1_weight'];}
    elseif(in_array($raw,['A2','3'],true)){$type='alt';$alt=2;$weight=(float)$weights['alt2_weight'];}
    elseif(in_array($raw,['A3','4'],true)){$type='alt';$alt=3;$weight=(float)$weights['alt3_weight'];}
    else throw new RuntimeException('Choose YES, A1, A2, A3 or NO.');

    if($type==='yes'){
        $limit=max(1,(int)($weights['yes_count']??10));
        $count=$pdo->prepare("SELECT COUNT(*) FROM bdc_scoring_marks m JOIN bdc_scoring_entries e ON e.id=m.entry_id WHERE m.round_id=:round AND m.judge_id=:judge AND e.dance_role=:role AND e.entry_status='active' AND m.mark_type='yes' AND m.entry_id<>:entry");
        $count->execute(['round'=>$roundId,'judge'=>$judgeId,'role'=>$role,'entry'=>$entryId]);
        if((int)$count->fetchColumn()>=$limit)throw new RuntimeException('Maximum '.$limit.' YES selections allowed for '.ucfirst($role).'s in this round. Clear or change another YES first.');
    }
    if($type==='alt'&&$alt!==null){
        $duplicate=$pdo->prepare("SELECT e.display_name FROM bdc_scoring_marks m JOIN bdc_scoring_entries e ON e.id=m.entry_id WHERE m.round_id=:round AND m.judge_id=:judge AND e.dance_role=:role AND e.entry_status='active' AND m.mark_type='alt' AND m.alt_rank=:alt AND m.entry_id<>:entry LIMIT 1");
        $duplicate->execute(['round'=>$roundId,'judge'=>$judgeId,'role'=>$role,'alt'=>$alt,'entry'=>$entryId]);
        if($name=$duplicate->fetchColumn())throw new RuntimeException('A'.$alt.' is already assigned to '.$name.' for '.ucfirst($role).'s. Each alternate rank can be used only once.');
    }

    $pdo->prepare("INSERT INTO bdc_scoring_marks(round_id,entry_id,judge_id,mark_type,alt_rank,weighted_score,updated_by) VALUES(:round,:entry,:judge,:type,:alt,:weight,NULL) ON DUPLICATE KEY UPDATE mark_type=VALUES(mark_type),alt_rank=VALUES(alt_rank),weighted_score=VALUES(weighted_score),updated_by=NULL,updated_at=NOW()")
        ->execute(['round'=>$roundId,'entry'=>$entryId,'judge'=>$judgeId,'type'=>$type,'alt'=>$alt,'weight'=>$weight]);
    return heatsSelectionState($pdo,$roundId,$judgeId,$role);
}

function saveFinalJudgeRank(PDO $pdo,int $roundId,int $judgeId,int $pairId,string $raw,int $rankLimit):void
{
    if($raw===''){$pdo->prepare('DELETE FROM bdc_scoring_final_marks WHERE round_id=:round AND pair_id=:pair AND judge_id=:judge')->execute(['round'=>$roundId,'pair'=>$pairId,'judge'=>$judgeId]);return;}
    if(!ctype_digit($raw))throw new RuntimeException('Enter a whole-number rank.');
    $countStmt=$pdo->prepare("SELECT COUNT(*) FROM bdc_scoring_final_pairs WHERE round_id=:round AND pairing_status='confirmed'");$countStmt->execute(['round'=>$roundId]);$count=(int)$countStmt->fetchColumn();
    $rank=(int)$raw;if($rank<1||$rank>$rankLimit)throw new RuntimeException('Ranks must be between 1 and '.$rankLimit.'.');
    $pair=$pdo->prepare("SELECT id FROM bdc_scoring_final_pairs WHERE id=:pair AND round_id=:round AND pairing_status='confirmed'");$pair->execute(['pair'=>$pairId,'round'=>$roundId]);if(!(int)$pair->fetchColumn())throw new RuntimeException('Final pair not found.');
    $duplicate=$pdo->prepare("SELECT pair_id FROM bdc_scoring_final_marks WHERE round_id=:round AND judge_id=:judge AND rank_value=:rank AND pair_id<>:pair LIMIT 1");$duplicate->execute(['round'=>$roundId,'judge'=>$judgeId,'rank'=>$rank,'pair'=>$pairId]);if($duplicate->fetchColumn())throw new RuntimeException('Rank '.$rank.' is already assigned to another couple.');
    $pdo->prepare("INSERT INTO bdc_scoring_final_marks(round_id,pair_id,judge_id,rank_value,updated_by) VALUES(:round,:pair,:judge,:rank,NULL) ON DUPLICATE KEY UPDATE rank_value=VALUES(rank_value),updated_by=NULL,updated_at=NOW()")
        ->execute(['round'=>$roundId,'pair'=>$pairId,'judge'=>$judgeId,'rank'=>$rank]);
}

function validateJudgeComplete(PDO $pdo,array $session,int $yesLimit,int $rankLimit):void
{
    $roundId=(int)$session['round_id'];$judgeId=(int)$session['judge_id'];
    if((string)$session['round_type']==='final'){
        $total=$pdo->prepare("SELECT COUNT(*) FROM bdc_scoring_final_pairs WHERE round_id=:round AND pairing_status='confirmed'");$total->execute(['round'=>$roundId]);$total=(int)$total->fetchColumn();
        if($total<1)throw new RuntimeException('Final pairing has not been confirmed yet.');
        $ranks=$pdo->prepare("SELECT rank_value FROM bdc_scoring_final_marks WHERE round_id=:round AND judge_id=:judge ORDER BY rank_value");$ranks->execute(['round'=>$roundId,'judge'=>$judgeId]);$values=array_map('intval',$ranks->fetchAll(PDO::FETCH_COLUMN));
        if(count($values)!==$rankLimit||$values!==range(1,$rankLimit))throw new RuntimeException('Assign each Top '.$rankLimit.' rank exactly once before submitting.');
        return;
    }
    $scope=(string)$session['scoring_scope'];
    foreach(['leader','follower'] as $role){
        if(!in_array($scope,['all',$role],true))continue;
        $totalStmt=$pdo->prepare("SELECT COUNT(*) FROM bdc_scoring_entries WHERE round_id=:round AND dance_role=:role AND entry_status='active'");$totalStmt->execute(['round'=>$roundId,'role'=>$role]);$total=(int)$totalStmt->fetchColumn();
        if($total<1||($total<=$yesLimit))continue;
        $state=heatsSelectionState($pdo,$roundId,$judgeId,$role);
        $requiredYes=$yesLimit;
        if($state['yes']!==$requiredYes)throw new RuntimeException('Select exactly '.$requiredYes.' YES for '.ucfirst($role).'s before submitting. Currently selected: '.$state['yes'].'.');
        $requiredAlternates=min(3,max(0,$total-$requiredYes));
        foreach(['A1','A2','A3'] as $index=>$alt){$required=$index<$requiredAlternates?1:0;if($state[$alt]!==$required)throw new RuntimeException(($required?'Select exactly one ':'Do not select ').$alt.' for '.ucfirst($role).'s before submitting.');}
    }
}

if($_SERVER['REQUEST_METHOD']==='POST'){
    try{
        $fresh=AutomaticJudgeBrowserService::byToken($pdo,$token);if(!$fresh)throw new RuntimeException('Judge scoring link expired.');
        $action=(string)($_POST['action']??'save');
        if($action==='accept_criteria'){
            if(($_POST['criteria_confirm']??'')!=='1')throw new RuntimeException('Confirm that you have read and accept the judging criteria.');
            AutomaticJudgeBrowserService::acceptCriteria($pdo,$sessionId);$session=AutomaticJudgeBrowserService::byToken($pdo,$token);$notice='Criteria accepted. You may begin scoring.';
        }elseif((string)$fresh['status']==='submitted')throw new RuntimeException('Your scores have already been submitted and locked.');
        elseif(JudgingCriteriaService::requiresAcceptance($fresh))throw new RuntimeException('Read and accept the judging criteria before scoring.');
        elseif($action==='save_score'){
            if($flightsEnabled){$subjectId=$isFinal?(int)($_POST['pair_id']??0):(int)($_POST['entry_id']??0);$map=ScoringFlightService::assignmentMap($pdo,$roundId,false,$isFinal?'pair':'entry');if((int)($map[$subjectId]['flight']??0)!==$viewRound)throw new RuntimeException('This competitor is not assigned to the selected scoring round.');}
            if($isFinal){saveFinalJudgeRank($pdo,$roundId,$judgeId,(int)($_POST['pair_id']??0),trim((string)($_POST['value']??'')),max(1,(int)($weights['callback_count']??1)));$state=null;}
            else $state=saveHeatsJudgeMark($pdo,$roundId,$judgeId,(int)($_POST['entry_id']??0),trim((string)($_POST['value']??'')),$weights);
            AutomaticJudgeBrowserService::markSaved($pdo,$sessionId);
            if(isset($_POST['ajax']))judgeJson(['ok'=>true,'saved_at'=>date('H:i:s'),'selection_state'=>$state]);
            $notice='Draft saved.';
        }elseif($action==='submit'){
            validateJudgeComplete($pdo,$fresh,$yesLimit,max(1,(int)($weights['callback_count']??1)));AutomaticJudgeBrowserService::submit($pdo,$sessionId);$locked=true;$notice='Scores submitted and locked. Thank you.';
        }
    }catch(Throwable $e){if(isset($_POST['ajax']))judgeJson(['ok'=>false,'error'=>$e->getMessage()],422);$error=$e->getMessage();}
}

$criteriaRequired=JudgingCriteriaService::requiresAcceptance($session);
if($criteriaRequired){
    $category=ucwords(str_replace('_',' ',(string)$session['division']));
    ?><!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Judging Criteria | BDC</title><style>*{box-sizing:border-box}body{margin:0;background:#f4f6f9;color:#172033;font-family:Arial,sans-serif}.top{background:linear-gradient(110deg,#111,#42101c);color:#fff;padding:22px 18px;border-bottom:5px solid #d10f32}.wrap{max-width:760px;margin:auto;padding:18px}.card{background:#fff;border:1px solid #dfe3e8;border-radius:14px;padding:20px;box-shadow:0 3px 12px rgba(15,23,42,.06)}.weights{display:grid;grid-template-columns:1fr 1fr;gap:8px}.weight{border:1px solid #dfe3e8;border-radius:9px;padding:10px;display:flex;justify-content:space-between}.rule{background:#eaf3ff;border-left:4px solid #0D6EFD;padding:12px;margin:16px 0}.rule ul{margin:8px 0 0;padding-left:20px}.rule li{margin:7px 0}.confirm{display:flex;gap:10px;align-items:flex-start;margin:18px 0}.start{width:100%;border:0;border-radius:10px;padding:14px;background:#146C43;color:#fff;font-size:17px;font-weight:800}.start:disabled{opacity:.4}.error{background:#ffe6e6;color:#8a1010;padding:12px;border-radius:9px;margin-bottom:12px}@media(max-width:520px){.weights{grid-template-columns:1fr}}</style></head><body><header class="top"><div class="wrap" style="padding:0"><strong>BDC AUTOMATIC SCORING</strong><h1><?=e($session['event_name'])?></h1><div><?=e($category)?> · <?=e(strtoupper((string)$session['round_type']))?> · <?=e($session['judge_name'])?></div></div></header><main class="wrap"><div class="card"><h2>Judging Criteria</h2><?php if($error):?><div class="error"><?=e($error)?></div><?php endif;?><div class="weights"><?php foreach(JudgingCriteriaService::weights() as [$name,$weight]):?><div class="weight"><strong><?=e($name)?></strong><span><?=e($weight)?></span></div><?php endforeach;?></div><div class="rule"><?php if($isFinal):?><strong>Final, Relative Placement:</strong> Rank your <strong>TOP <?=$configuredFinalRankLimit?></strong> best couples from 1 to <?=$configuredFinalRankLimit?>. Use each rank once. Leave all other couples as <strong>NO RANK</strong>.<?php else:?><strong><?=e($selectionRoundLabel)?> Instructions</strong><ul><li>Choose <strong><?=$yesLimit?> YES</strong> for your <strong>Top <?=$yesLimit?> best dancers</strong>.</li><li>Alternative picks: A1 = <strong><?=e($a1Place)?> place</strong>, A2 = <strong><?=e($a2Place)?> place</strong>, A3 = <strong><?=e($a3Place)?> place</strong>.</li><li>Mark everyone else <strong>NO</strong>.</li><li>Use the optional comment field for a private note.</li></ul><?php endif;?></div><p>Judge independently and confidentially. Do not discuss or compare selections with another judge before submitting.</p><form method="post"><input type="hidden" name="token" value="<?=e($token)?>"><input type="hidden" name="action" value="accept_criteria"><label class="confirm"><input id="criteriaConfirm" type="checkbox" name="criteria_confirm" value="1"><span>I have read and accept the judging criteria.</span></label><button id="startScoring" class="start" disabled>Start Scoring</button></form></div></main><script>const c=document.getElementById('criteriaConfirm'),b=document.getElementById('startScoring');c.onchange=()=>b.disabled=!c.checked;</script></body></html><?php
    exit;
}

$initialState=['leader'=>['yes'=>0,'A1'=>0,'A2'=>0,'A3'=>0],'follower'=>['yes'=>0,'A1'=>0,'A2'=>0,'A3'=>0]];
if($isFinal){
    $flightJoin=$flightsEnabled?' JOIN bdc_scoring_flight_assignments fa ON fa.round_id=fp.round_id AND fa.subject_type=\'pair\' AND fa.subject_id=fp.id AND fa.flight_number=:flight ':'';
    $stmt=$pdo->prepare("SELECT fp.id pair_id,fp.pair_number,le.display_name leader_name,le.bib_number leader_bib,fe.display_name follower_name,fe.bib_number follower_bib,fm.rank_value FROM bdc_scoring_final_pairs fp {$flightJoin} JOIN bdc_scoring_entries le ON le.id=fp.leader_entry_id JOIN bdc_scoring_entries fe ON fe.id=fp.follower_entry_id LEFT JOIN bdc_scoring_final_marks fm ON fm.round_id=fp.round_id AND fm.pair_id=fp.id AND fm.judge_id=:judge WHERE fp.round_id=:round AND fp.pairing_status='confirmed' ORDER BY fp.pair_number");
    $finalParams=['judge'=>$judgeId,'round'=>$roundId];if($flightsEnabled)$finalParams['flight']=$viewRound;$stmt->execute($finalParams);$pairs=$stmt->fetchAll();$totalPairsStmt=$pdo->prepare("SELECT COUNT(*) FROM bdc_scoring_final_pairs WHERE round_id=:round AND pairing_status='confirmed'");$totalPairsStmt->execute(['round'=>$roundId]);$finalRankLimit=min((int)$totalPairsStmt->fetchColumn(),max(1,(int)($weights['callback_count']??count($pairs))));
}else{
    $scope=(string)$session['scoring_scope'];
    $flightJoin=$flightsEnabled?' JOIN bdc_scoring_flight_assignments fa ON fa.round_id=e.round_id AND fa.subject_type=\'entry\' AND fa.subject_id=e.id AND fa.flight_number=:flight ':'';
    $stmt=$pdo->prepare("SELECT e.id,e.dance_role,e.bib_number,e.display_name,m.mark_type,m.alt_rank FROM bdc_scoring_entries e {$flightJoin} LEFT JOIN bdc_scoring_marks m ON m.round_id=e.round_id AND m.entry_id=e.id AND m.judge_id=:judge WHERE e.round_id=:round AND e.entry_status='active' AND (:scope='all' OR e.dance_role=:scope2) ORDER BY e.dance_role,e.bib_number");
    $entryParams=['judge'=>$judgeId,'round'=>$roundId,'scope'=>$scope,'scope2'=>$scope];if($flightsEnabled)$entryParams['flight']=$viewRound;$stmt->execute($entryParams);$allEntries=$stmt->fetchAll();$entries=['leader'=>[],'follower'=>[]];foreach($allEntries as $entry){$entryRole=(string)$entry['dance_role'];if($rolePlan[$entryRole]['direct_to_final']??false)continue;$entry['current_mark']=$entry['mark_type']==='yes'?'YES':($entry['mark_type']==='alt'?'A'.(int)$entry['alt_rank']:'');$entries[$entryRole][]=$entry;}
    foreach(['leader','follower'] as $role)if($entries[$role])$initialState[$role]=heatsSelectionState($pdo,$roundId,$judgeId,$role);
}
$roleTotals=['leader'=>0,'follower'=>0];if(!$isFinal){foreach(['leader','follower'] as $totalRole){$allowed=(string)$session['scoring_scope']==='all'||(string)$session['scoring_scope']===$totalRole;if($allowed&&!($rolePlan[$totalRole]['direct_to_final']??false))$roleTotals[$totalRole]=$allRoleCounts[$totalRole];}}
$category=ucwords(str_replace('_',' ',(string)$session['division']));
?>
<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Judge Scoring | BDC</title><style>
