function showRuleMessage(message){const box=document.getElementById('ruleMessage');if(!box)return;box.textContent=message;box.style.display='block';clearTimeout(showRuleMessage.timer);showRuleMessage.timer=setTimeout(()=>box.style.display='none',4500)}
function roleReady(role){const total=Number(roleTotals[role]||0);if(!total)return true;const state=selectionState[role]||{yes:0,A1:0,A2:0,A3:0},requiredYes=Math.min(yesLimit,total),requiredAlts=Math.min(3,Math.max(0,total-requiredYes));return !document.querySelector('[data-entry-card][data-role="'+role+'"][data-saving="1"]')&&state.yes===requiredYes&&['A1','A2','A3'].every((alt,index)=>state[alt]===(index<requiredAlts?1:0))}
function updateSubmitReadiness(){const button=document.getElementById('submitScores');if(!button)return;if(<?=json_encode($isFinal)?>){const ranks=[...document.querySelectorAll('.judge-input')].map(input=>parseInt(input.value||'0',10)).filter(Boolean),ready=ranks.length===finalRankLimit&&new Set(ranks).size===finalRankLimit&&ranks.every(rank=>rank>=1&&rank<=finalRankLimit);button.disabled=!ready;button.textContent=ready?'READY TO SUBMIT FINAL':'COMPLETE TOP '+finalRankLimit;return}const ready=['leader','follower'].every(role=>roleReady(role));button.disabled=!ready;button.textContent=ready?'READY TO SUBMIT':'COMPLETE REQUIRED SELECTIONS'}
function updateCounter(role){const state=selectionState[role]||{yes:0,A1:0,A2:0,A3:0},el=document.querySelector('[data-counter="'+role+'"]');if(!el)return;el.innerHTML='<span class="counter-item counter-yes">YES '+state.yes+' / '+yesLimit+'</span><span class="counter-item counter-a1">A1 '+state.A1+' / 1</span><span class="counter-item counter-a2">A2 '+state.A2+' / 1</span><span class="counter-item counter-a3">A3 '+state.A3+' / 1</span>';el.classList.toggle('over',state.yes>yesLimit||state.A1>1||state.A2>1||state.A3>1);el.style.borderColor=roleReady(role)?'#198754':'';updateAvailability(role);updateSubmitReadiness()}
function updateAvailability(role){const state=selectionState[role]||{yes:0,A1:0,A2:0,A3:0};document.querySelectorAll('[data-entry-card][data-role="'+role+'"]').forEach(card=>{const current=card.querySelector('.choice.active')?.dataset.value||'';card.querySelectorAll('.choice').forEach(button=>{const value=button.dataset.value,full=value==='YES'?state.yes>=yesLimit:(['A1','A2','A3'].includes(value)&&state[value]>=1);button.style.opacity=full&&current!==value?'.42':'1';button.setAttribute('aria-disabled',full&&current!==value?'true':'false')})})}
function localRuleCheck(button){const card=button.closest('[data-entry-card]');if(!card)return true;const role=card.dataset.role,state=selectionState[role]||{yes:0,A1:0,A2:0,A3:0},current=card.querySelector('.choice.active')?.dataset.value||'',next=button.dataset.value;if(next==='YES'&&current!=='YES'&&state.yes>=yesLimit){showRuleMessage('Maximum '+yesLimit+' YES selections allowed for '+(role==='leader'?'Leaders':'Followers')+'. Clear or change another YES first.');return false;}if(['A1','A2','A3'].includes(next)&&current!==next&&state[next]>=1){showRuleMessage(next+' is already used for '+(role==='leader'?'Leaders':'Followers')+'. Each alternate rank can be used only once.');return false;}return true}
function adjustLocalState(card,newValue){if(!card)return;const role=card.dataset.role,state=selectionState[role],old=card.querySelector('.choice.active')?.dataset.value||'';if(old==='YES')state.yes=Math.max(0,state.yes-1);else if(['A1','A2','A3'].includes(old))state[old]=Math.max(0,state[old]-1);if(newValue==='YES')state.yes++;else if(['A1','A2','A3'].includes(newValue))state[newValue]++;updateCounter(role)}
function htmlEscape(value){return String(value??'').replace(/[&<>"']/g,char=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[char]))}
async function saveChoice(button){
 const card=button.closest?button.closest('[data-entry-card]'):null;if(card&&card.dataset.saving==='1')return;if(card&&!localRuleCheck(button))return;
 const saved=card?card.querySelector('.saved'):button.parentElement.querySelector('.saved'),oldButton=card?card.querySelector('.choice.active'):null,oldValue=oldButton?.dataset.value||'';
 if(card){card.dataset.saving='1';adjustLocalState(card,button.dataset.value);card.querySelectorAll('.choice').forEach(x=>x.classList.remove('active'));button.classList.add('active');updateAvailability(card.dataset.role)}
 if(saved){saved.textContent='Saving…';saved.classList.remove('fail')}
 const body=new URLSearchParams({token:token,action:'save_score',ajax:'1',value:button.dataset.value,scoring_round:String(<?=json_encode($viewRound)?>)});if(button.dataset.entry)body.set('entry_id',button.dataset.entry);if(button.dataset.pair)body.set('pair_id',button.dataset.pair);
 try{const r=await fetch(location.href,{method:'POST',headers:{'Content-Type':'application/x-www-form-urlencoded','Accept':'application/json','X-Requested-With':'XMLHttpRequest'},body:body.toString()});if(r.status===429)throw new Error('Server is busy. Please wait a moment and tap the rank again.');const text=await r.text();let data;try{data=JSON.parse(text)}catch(parseError){throw new Error('Score save response was interrupted. Please tap the rank again.')}if(!r.ok||!data.ok)throw new Error(data.error||'Save failed');if(card){const role=card.dataset.role;if(data.selection_state){selectionState[role]=data.selection_state;updateCounter(role)}}if(saved)saved.textContent='Saved '+data.saved_at;updateSubmitReadiness();}
 catch(e){if(card){adjustLocalState(card,oldValue);card.querySelectorAll('.choice').forEach(x=>x.classList.remove('active'));oldButton?.classList.add('active');updateAvailability(card.dataset.role)}if(saved){saved.textContent=e.message;saved.classList.add('fail')}showRuleMessage(e.message)}
 finally{if(card)delete card.dataset.saving;updateSubmitReadiness()}
}
document.querySelectorAll('.choice').forEach(button=>button.addEventListener('click',()=>saveChoice(button)));
document.querySelectorAll('.heats-comment-input').forEach(input=>{const commentKey='bdc-heats-comment-<?=$roundId?>-<?=$judgeId?>-'+input.dataset.entry;input.value=localStorage.getItem(commentKey)||'';input.addEventListener('input',()=>localStorage.setItem(commentKey,input.value));});
function updateFinalRankButtons(){const inputs=[...document.querySelectorAll(".judge-input")],used=new Set(inputs.map(input=>input.value).filter(Boolean));document.querySelectorAll("[data-final-card]").forEach(card=>{const input=card.querySelector(".judge-input"),current=input.value,placed=current!=="";card.classList.toggle("is-placed",placed);const badge=card.querySelector(".placement-badge");if(badge)badge.textContent=placed?"PLACED #"+current:"NO RANK";card.querySelectorAll(".rank-button").forEach(button=>{const selected=current===button.dataset.rank;button.classList.toggle("selected",selected);button.classList.toggle("used",used.has(button.dataset.rank)&&!selected);button.disabled=false;button.setAttribute("aria-pressed",selected?"true":"false")});const noRank=card.querySelector(".rank-clear");noRank.classList.toggle("selected",!placed);noRank.setAttribute("aria-pressed",placed?"false":"true")});const available=[];for(let rank=1;rank<=finalRankLimit;rank++)if(!used.has(String(rank)))available.push(rank);const summary=document.getElementById("rankAvailableSummary");if(summary)summary.innerHTML="<span class=\"rank-progress\">Placed "+used.size+" of "+finalRankLimit+"</span><br><span class=\"rank-missing\">"+(available.length?"Missing: "+available.join(", "):"All placements complete")+"</span>";}
async function persistFinalRank(input){updateFinalRankButtons();const fake={dataset:{value:input.value,pair:input.dataset.pair},parentElement:input.closest('[data-final-card]'),closest:()=>null};await saveChoice(fake);input.dataset.previous=input.value;updateFinalRankButtons();updateSubmitReadiness();}
document.querySelectorAll('.judge-input').forEach(input=>{input.dataset.previous=input.value;input.addEventListener('change',async()=>{const duplicate=[...document.querySelectorAll('.judge-input')].find(other=>other!==input&&input.value!==''&&other.value===input.value);if(duplicate){const rank=input.value,replace=confirm('Rank '+rank+' is already assigned to '+duplicate.dataset.label+'. Assign it to '+input.dataset.label+' and change '+duplicate.dataset.label+' to NO RANK?');if(!replace){input.value=input.dataset.previous;updateFinalRankButtons();return;}duplicate.value='';updateFinalRankButtons();await persistFinalRank(duplicate);showRuleMessage(duplicate.dataset.label+' is now NO RANK. Rank '+rank+' has been assigned to '+input.dataset.label+'.');}await persistFinalRank(input)})});
document.querySelectorAll('[data-final-card]').forEach(card=>{const input=card.querySelector('.judge-input');card.querySelectorAll('.rank-button').forEach(button=>button.addEventListener('click',()=>{input.value=button.dataset.rank;input.dispatchEvent(new Event('change'))}));card.querySelector('.rank-clear').addEventListener('click',()=>{input.value='';input.dispatchEvent(new Event('change'))});});
document.querySelectorAll('.competitor-comment-input').forEach(input=>{const commentKey='bdc-final-comment-<?=$roundId?>-<?=$judgeId?>-'+input.dataset.pair;input.value=localStorage.getItem(commentKey)||'';input.addEventListener('input',()=>localStorage.setItem(commentKey,input.value));});
const rankFilterToggle=document.getElementById('rankFilterToggle');if(rankFilterToggle){const filterKey='bdc-final-rank-filter-<?=$roundId?>-<?=$judgeId?>';const applyRankFilter=enabled=>{document.body.classList.toggle('rank-filter-on',enabled);rankFilterToggle.classList.toggle('active',enabled);rankFilterToggle.textContent=enabled?'Show All Ranks':'Grey Out Used Ranks';rankFilterToggle.setAttribute('aria-pressed',enabled?'true':'false');localStorage.setItem(filterKey,enabled?'1':'0')};applyRankFilter(localStorage.getItem(filterKey)==='1');rankFilterToggle.addEventListener('click',()=>applyRankFilter(!document.body.classList.contains('rank-filter-on')));}
function updateFinalRankingReview(){const cards=[...document.querySelectorAll('[data-final-card]')],placements=new Map();cards.forEach(card=>{const rank=parseInt(card.querySelector('.judge-input')?.value||'0',10);if(rank)placements.set(rank,{card,bibs:card.querySelector('.bib')?.textContent.trim()||''})});const rows=[];for(let rank=1;rank<=finalRankLimit;rank++){const item=placements.get(rank),complete=!!item;rows.push('<tr class="'+(complete?'complete':'missing')+'" data-review-rank="'+rank+'"><td>'+rank+'</td><td>'+(complete?htmlEscape(item.bibs):'— NOT SELECTED —')+'</td></tr>')}const split=Math.ceil(rows.length/2),placed=placements.size,missing=[];for(let rank=1;rank<=finalRankLimit;rank++)if(!placements.has(rank))missing.push(rank);const left=document.getElementById('rankingReviewLeft'),right=document.getElementById('rankingReviewRight'),mobile=document.getElementById('rankingReviewMobile');if(left)left.innerHTML=rows.slice(0,split).join('');if(right)right.innerHTML=rows.slice(split).join('');if(mobile)mobile.innerHTML=rows.join('');const open=document.getElementById('rankingReviewOpen'),progress=document.getElementById('rankingReviewProgress'),missingBox=document.getElementById('rankingReviewMissing');if(open)open.textContent='View My Ranking · '+placed+'/'+finalRankLimit;if(progress)progress.textContent=placed+' of '+finalRankLimit+' placements completed';if(missingBox)missingBox.textContent=missing.length?'Missing placements: '+missing.join(', '):'All placements completed';document.querySelectorAll('[data-review-rank]').forEach(row=>row.onclick=()=>{const item=placements.get(parseInt(row.dataset.reviewRank,10));if(!item)return;document.getElementById('rankingReviewDialog')?.close();item.card.scrollIntoView({behavior:'smooth',block:'center'})})}
const rankingReviewDialog=document.getElementById('rankingReviewDialog'),rankingReviewOpen=document.getElementById('rankingReviewOpen');if(rankingReviewOpen&&rankingReviewDialog){rankingReviewOpen.addEventListener('click',()=>{updateFinalRankingReview();rankingReviewDialog.showModal()});document.getElementById('rankingReviewClose')?.addEventListener('click',()=>rankingReviewDialog.close());document.getElementById('rankingReviewContinue')?.addEventListener('click',()=>rankingReviewDialog.close());rankingReviewDialog.addEventListener('click',event=>{if(event.target===rankingReviewDialog)rankingReviewDialog.close()});document.querySelectorAll('.judge-input').forEach(input=>input.addEventListener('change',()=>{updateFinalRankingReview();setTimeout(updateFinalRankingReview,500)}));updateFinalRankingReview()}
document.querySelectorAll('.tab').forEach(button=>button.addEventListener('click',()=>{document.querySelectorAll('.tab').forEach(x=>x.classList.toggle('active',x===button));document.querySelectorAll('.panel').forEach(panel=>panel.classList.toggle('active',panel.dataset.panel===button.dataset.tab));}));
updateFinalRankButtons();updateCounter('leader');updateCounter('follower');updateSubmitReadiness();
</script><?php endif;?></body></html>
